package api.auth.kimdeo.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
data class PlayingVideoModelJob(
    val startTime: Double = 0.0,
    val endTime: Double = 0.0,
)


// generate audio voice when video is playing model
@Serializable
data class GenerateVoiceWVIPModel(
    @SerialName("email")
    val email: String,
    @SerialName("json_file_path")
    val jsonFilePath: String,
    @SerialName("job_id")
    val jobId: String,
    @SerialName("language_code")
    val languageCode: String,
    @SerialName("start_time")
    val startTime: Double,
)



@Serializable
data class WebSocketJobModel<T>(
    @SerialName("ws_id") val wsId: String,
    @SerialName("message") val message: String,
    @SerialName("job_status") val jobStatus: JobStatus,
    @SerialName("complete_percentage") val completePercent: Double = 0.0,
    @SerialName("data_type") val dataType: T? = null,
)


@Serializable
data class GenerateVoiceWVIPModelFree(
    @SerialName("json_file_path")
    val jsonFilePath: String,
    @SerialName("language_code")
    val languageCode: String,
    @SerialName("start_time")
    val startTime: Double,
    @SerialName("folder_id")
    val folderId: String,
)