private data class BaseScreenItem(
    val title: String,
    val icon: @Composable () -> Unit,
    val screen: Screen,
    val screenType: ScreenType
)

private val baseScreens = listOf(
    BaseScreenItem(
        "Video",
        { Icon(TablerIcons.Video, null, tint = MaterialTheme.colorScheme.inversePrimary) },
        KimdeoPlayerScreen,
        ScreenType.VIDEOPLAYER
    ),
    BaseScreenItem(
        "Transcription",
        { Icon(TablerIcons.Files, null, tint = MaterialTheme.colorScheme.inversePrimary) },
        TranscribingScreen(),
        ScreenType.TRANSCRIBING
    ),
    BaseScreenItem("Profile", { Icon(TablerIcons.UserX, null, tint = MaterialTheme.colorScheme.inversePrimary) }, ProfileScreen, ScreenType.PROFILE),
    BaseScreenItem(
        "Settings",
        { Icon(TablerIcons.Settings, null, tint = MaterialTheme.colorScheme.inversePrimary) },
        SettingsScreen,
        ScreenType.SETTINGS
    ),
)

object BaseScreen : Screen {

    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val screenModel = rememberScreenModel { BaseScreenModel() }
        val startScreen = remember {
            val s = PreferenceManager.getScreen()
            baseScreens.find { it.screenType == s }?.screen
                ?: TranscribingScreen()
        }
        LaunchedEffect(Unit) {
            val s = PreferenceManager.getScreen()
            if (s == ScreenType.NONE) PreferenceManager.saveScreen(ScreenType.TRANSCRIBING)
        }
        val st = screenModel.screenName.collectAsStateWithLifecycle()
        Navigator(startScreen) { navigator ->

            val isPortrait = deviceInfo.orientation == Orientation.PORTRAIT

            if (isPortrait) {
                SideDrawer(
                    modifier = Modifier.width(
                        PixelDensity.getPixelDensity(
                            deviceInfo.width.toPercentage(50)
                        )
                    ),
                    navigator = navigator,
                    screenModel = screenModel,
                )
            } else {
                MainScaffold(
                    topBar = {
                        if (st.value != ScreenType.NONE) {
                            AppTopBar(
                                actions = {
                                    baseScreens.forEach { item ->
                                        TopBarItem(item, navigator, screenModel)
                                    }
                                }
                            )
                        }
                    }
                )
            }
        }
    }

    @Composable
    private fun TopBarItem(
        item: BaseScreenItem,
        navigator: Navigator,
        screenModel: BaseScreenModel
    ) {
        val st by screenModel.screenName.collectAsStateWithLifecycle()
        HorizontalTextIcon(
            modifier = Modifier
                .clickable {
                    navigator.navigateReplace(item.screen, item.screenType)
                }
                .underlineIf(
                    st == item.screenType,
                    color = MaterialTheme.colorScheme.inversePrimary
                )
                .padding(horizontal = PixelDensity.MEDIUM),
            text = item.title,
            style = MaterialTheme.typography.bodyMedium.copy(
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onTertiary
            ),
            leadingContent = {
                item.icon()
            }
        )
    }

    @Composable
    private fun SideDrawer(modifier: Modifier, navigator: Navigator, screenModel: BaseScreenModel) {
        val drawerState = rememberDrawerState(DrawerValue.Closed)
        val scope = rememberCoroutineScope()
        val imageBitmap = remember(screenModel.profileImage) {
            if (screenModel.profileImage == null) null
            else (screenModel.profileImage as ByteArray).decodeToImageBitmap()
        }
        val st by screenModel.screenName.collectAsStateWithLifecycle()
//        var selected by remember { mutableStateOf(baseScreens.first()) }
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                if (st != ScreenType.NONE) {
                    ModalDrawerSheet(
                        modifier = modifier,
                        drawerContainerColor = MaterialTheme.colorScheme.tertiary, // 👈 background
                        drawerContentColor = MaterialTheme.colorScheme.onTertiary  // 👈 text/icons
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                        ) {
                            Box(
                                Modifier.fillMaxWidth(),
                                contentAlignment = Alignment.Center
                            ) {
                                if (imageBitmap != null) {
                                    Image(
                                        contentScale = ContentScale.Inside,
                                        bitmap = imageBitmap,
                                        contentDescription = null,
                                    )
                                } else {
                                    Image(
                                        contentScale = ContentScale.Inside,
                                        painter = painterResource(Res.drawable.user),
                                        contentDescription = null,
                                    )
                                }
                            }
                            baseScreens.forEach { item ->
                                HorizontalTextIcon(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(PixelDensity.SMALL)
                                        .clickable(onClick = {
                                            scope.launch { drawerState.close() }
                                            navigator.navigateReplace(item.screen, item.screenType)
                                        })
                                        .background(
                                            shape = MaterialTheme.shapes.small,
                                            color = if (item.screenType == st) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.secondary
                                        ).padding(PixelDensity.MEDIUM),
                                    leadingContent = item.icon,
                                    text = item.title,
                                    style = MaterialTheme.typography.bodyMedium.copy(
                                        fontWeight = FontWeight.Bold,
                                        color = if (item.screenType == st) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSecondary
                                    )
                                )
                            }
                        }
                    }
                }
            }
        ) {
            MainScaffold(topBar = {
                if (st != ScreenType.NONE) {
                    AppTopBar(onClick = { scope.launch { drawerState.open() } }
                    )
                }
            })
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    private fun AppTopBar(
        actions: @Composable RowScope.() -> Unit = {},
        onClick: (() -> Unit)? = null
    ) {
        TopAppBar(
            colors = TopAppBarDefaults.topAppBarColors(
                containerColor = MaterialTheme.colorScheme.tertiary,
                titleContentColor = MaterialTheme.colorScheme.onTertiary,
                navigationIconContentColor = MaterialTheme.colorScheme.onTertiary,
            ),
            navigationIcon = {
                if (onClick != null) {
                    IconButton(onClick = onClick) {
                        Icon(
                            TablerIcons.LayoutList,
                            null
                        )
                    }
                }
            },
            title = {
                Text("KimDeo", style = MaterialTheme.typography.headlineSmall)
            },
            actions = actions
        )
    }

    @Composable
    private fun MainScaffold(
        topBar: @Composable () -> Unit,
    ) {
        val screenModel = rememberScreenModel { BaseScreenModel() }
        val invokeLogin by screenModel.invokeLogin.collectAsStateWithLifecycle()
        val navigator = LocalNavigator.currentOrThrow
        Scaffold(
            modifier = Modifier.fillMaxSize()
                .windowInsetsPadding(WindowInsets.safeDrawing),
            topBar = topBar
        ) { pv ->
            Box(Modifier.padding(pv), contentAlignment = Alignment.Center) {
                DisplayToast(
                    show = invokeLogin.shouldLogin && invokeLogin.alreadyLogin,
                    durationSeconds = screenModel.invokeLoginCountDown,
                    onDismiss = {
                        navigator.popUntilRoot()
                    },
                    content = { duration ->
                        Column(
                            modifier = Modifier.outline(
                                width = PixelDensity.VERY_SMALL,
                                bgColor = MaterialTheme.colorScheme.onBackground,
                                padding = PixelDensity.MEDIUM
                            ),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(
                                PixelDensity.MEDIUM
                            )
                        ) {
                            Text(
                                "Your session has Expire and you will be redirected to log in page in",
                                style = MaterialTheme.typography.bodyMedium
                            )
                            Text(
                                duration.toString(),
                                style = MaterialTheme.typography.headlineLarge
                            )
                        }
                    }
                )
                CurrentScreen()
            }
        }
    }
}
