class TranscribingScreen(private val transcribeJobModel: TranscribeJobModel? = null) : Screen {
    @Composable
    override fun Content() {
        val screenModel = rememberScreenModel { TranscriptionScreenModel(transcribeJobModel) }
        val deviceInfo = rememberDeviceInfo()
        val navigator = LocalNavigator.currentOrThrow
        Scaffold(
            modifier = Modifier.fillMaxSize(),
            floatingActionButton = {
                if (deviceInfo.orientation == Orientation.PORTRAIT && !screenModel.transcribeJobPopup.show) {
                    SmallFloatingActionButton(
                        onClick = {
                            screenModel.updattranscribeJobPopup(PopupModel(show = true))
                        }, content = {
                            Icon(
                                modifier = Modifier
                                    .clip(CircleShape)
                                    .displayShimmer(
                                        speed = 2000,
                                        colors = if (screenModel.transcribeJobModel != null) {
                                            listOf(
                                                Color.Green,
                                                Color.Cyan,
                                            )
                                        } else {
                                            listOf(
                                                MaterialTheme.colorScheme.surface.copy(
                                                    alpha = 0.5f
                                                ),
                                                MaterialTheme.colorScheme.onSurface.copy(
                                                    alpha = 0.5f
                                                ),
                                            )
                                        }
                                    )
                                    .padding(PixelDensity.MEDIUM),
                                imageVector = if (screenModel.transcribeJobModel != null) TablerIcons.HandFinger else TablerIcons.HandOff,
                                contentDescription = "transcription is availability",
                            )
                        })
                }
            },
            content = { pv ->
                DisplayToast(
                    show = screenModel.toastPopup.show,
                    onDismiss = { screenModel.toastPopup = PopupModel() },
                    content = {
                        HorizontalTextIcon(
                            leadingContent = { screenModel.transcribingScreenPopup.content() },
                            text = screenModel.transcribingScreenPopup.description,
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                        )
                    }
                )
                DisplayPopup(
                    show = screenModel.transcribingScreenPopup.show,
                    onDismiss = { screenModel.updateTranscribeScreenPopup(PopupModel()) },
                    content = {
                        Column(
                            modifier = Modifier.background(color = MaterialTheme.colorScheme.onBackground)
                                .padding(
                                    PixelDensity.MEDIUM
                                ), verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                        ) {
                            HorizontalTextIcon(
                                leadingContent = { screenModel.transcribingScreenPopup.content() },
                                text = screenModel.transcribingScreenPopup.title,
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.background
                                )
                            )
                            Text(
                                text = screenModel.transcribingScreenPopup.description,
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.background
                                )
                            )
                        }
                    }
                )
                DisplayPopup(
                    show = screenModel.transcribeJobPopup.show,
                    contentAlignment = Alignment.BottomCenter,
                    onDismiss = { screenModel.updattranscribeJobPopup(PopupModel()) },
                    content = {
                        TranscriptionDisplay(modifier = Modifier.fillMaxWidth())
                    }
                )

                when (screenModel.connectionState) {
                    is ConnectionState.OnFailure -> {
                        Column(
                            Modifier.fillMaxSize().padding(pv).padding(PixelDensity.SMALL),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center
                        ) {
                            ShimmeringText(text = (screenModel.connectionState as ConnectionState.OnFailure).data)
                            GobackOrReload(
                                modifier = Modifier.padding(top = PixelDensity.LARGE),
                                reloadVisible = screenModel.connectionState is ConnectionState.OnFailure,
                                backVisible = navigator.canPop,
                                colors = listOf(
                                    MaterialTheme.colorScheme.primary,
                                    MaterialTheme.colorScheme.background
                                ),
                                bgColors = listOf(
                                    MaterialTheme.colorScheme.tertiary,
                                    MaterialTheme.colorScheme.surface.copy(alpha = 0.5f)
                                ),
                                reload = { screenModel.initializeScreenModel() },
                                onBack = {navigator.pop()}
                            )
                        }
                    }

                    is ConnectionState.OnSucsess -> {
                        when (deviceInfo.orientation) {
                            Orientation.PORTRAIT -> {
                                Column(
                                    modifier = Modifier.fillMaxSize().padding(pv)
                                        .padding(PixelDensity.VERY_SMALL),
                                    verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                                ) {
                                    TranscriptionConfigurationDisplay(
                                        modifier = Modifier.fillMaxWidth()
                                            .padding(PixelDensity.MEDIUM)
                                            .verticalScrollable(),
                                    )
                                }
                            }

                            else -> {
                                Row(
                                    modifier = Modifier.fillMaxSize().padding(pv)
                                        .padding(PixelDensity.VERY_SMALL)
                                        .padding(PixelDensity.MEDIUM),
                                    horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                                ) {
                                    TranscriptionConfigurationDisplay(
                                        modifier = Modifier.weight(1f).verticalScrollable(),
                                    )
                                    TranscriptionDisplay(
                                        modifier = Modifier.weight(1f),
                                    )
                                }
                            }
                        }
                    }

                    else -> {
                        Column(
                            Modifier.fillMaxSize().padding(pv).padding(PixelDensity.VERY_SMALL),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center
                        ) {
                            val pulseBeforeShow = produceState(initialValue = false) {
                                delay(5000)
                                value = true
                            }
                            PulsingRing()
                            if (pulseBeforeShow.value) {
                                ShimmeringText(
                                    modifier = Modifier.padding(top = PixelDensity.LARGE),
                                    "Loading... seems to be taking a lot of time."
                                )
                                GobackOrReload(
                                    modifier = Modifier.padding(top = PixelDensity.LARGE),
                                    reloadVisible = screenModel.connectionState is ConnectionState.OnFailure,
                                    backVisible = navigator.canPop,
                                    colors = listOf(
                                        MaterialTheme.colorScheme.primary,
                                        MaterialTheme.colorScheme.background
                                    ),
                                    bgColors = listOf(
                                        MaterialTheme.colorScheme.tertiary,
                                        MaterialTheme.colorScheme.surface.copy(alpha = 0.5f)
                                    ),
                                    reload = { screenModel.initializeScreenModel() },
                                    onBack = {navigator.pop()}
                                )
                            }
                        }
                    }
                }
            })
    }


