package api.auth.kimdeo.model.plan

import api.auth.kimdeo.utils.toReadableCommaFormat
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable


@Serializable
enum class PlanInterval(val amount: Double, val planCode: String, val credits: Int) {
    @SerialName("one_time")
    ONE_TIME(12000.0, "", 4000),

    @SerialName("bonus_plan")
    BONUS_PLAN(1000.0, "", 100),

    @SerialName("monthly")
    MONTHLY(6000.0, "PLN_3v522uyxe2345vs", 2000), //orenua
    // MONTHLY(6.0, "PLN_7hniute8ub7qac3", 2000), // fictioneer

    @SerialName("annually")
    YEARLY(70000.0, "PLN_9wzvgejyjgmhzb4", 24000), //orenua
    // YEARLY(60.0, "PLN_06gmkfqlzv8jz84", 24000), // fictioneer
}

@Serializable
data class PlanModel(
    val name: String,
    val description: String,
    val price: Double,
    val credits: Int,
    val interval: PlanInterval,
    val features: List<String>,
)

val ONE_TIME_PLAN = PlanModel(
    name = "One-Time Package",
    description = "Flexible pay-as-you-go access with no recurring commitment.",
    price = PlanInterval.ONE_TIME.amount,
    credits = PlanInterval.ONE_TIME.credits,
    interval = PlanInterval.ONE_TIME,
    features = listOf(
        "Instant credit allocation",
        "No subscription required",
        "pay for what you need",
        "Priority support"
    )
)

val BONUS_PLAN = PlanModel(
    name = "Bonus Package",
    description = "Flexible bonus access with no recurring commitment.",
    price = PlanInterval.BONUS_PLAN.amount,
    credits = PlanInterval.BONUS_PLAN.credits,
    interval = PlanInterval.BONUS_PLAN,
    features = listOf(
        "Instant credit allocation",
        "No subscription required",
        "pay for what you need",
        "Priority support"
    )
)

val MONTHLY_PLAN = PlanModel(
    name = "Monthly Subscription",
    description = "Affordable monthly access with consistent credit allocation.",
    price = PlanInterval.MONTHLY.amount,
    credits = PlanInterval.MONTHLY.credits,
    interval = PlanInterval.MONTHLY,
    features = listOf(
        "${PlanInterval.MONTHLY.credits.toReadableCommaFormat()} credits every month",
        "Automatic renewal",
        "Cancel anytime",
        "Standard support"
    )
)

val YEARLY_PLAN = PlanModel(
    name = "Annual Subscription",
    description = "Best value plan with significant savings and premium benefits.",
    price = PlanInterval.YEARLY.amount,
    credits = PlanInterval.YEARLY.credits,
    interval = PlanInterval.YEARLY,
    features = listOf(
        "${PlanInterval.YEARLY.credits.toReadableCommaFormat()} credits per year",
        "Discounted annual pricing",
        "Priority customer support",
        "Early access to new features"
    )
)
