sealed class ConnectionState() {
    data class OnSucsess(val data: String) : ConnectionState()
    data class OnFailure(val data: String) : ConnectionState()
    object OnLoading : ConnectionState()
    object None : ConnectionState()
}

sealed class FileConnectionState {
    data class OnGotten(val data: String) : FileConnectionState()
    data class OnSuccess(val data: String) : FileConnectionState()
    data class OnFailure(val data: String) : FileConnectionState()
    object OnUploading : FileConnectionState()
    object None : FileConnectionState()
}


@Composable
fun PulsingRing() {
    val infiniteTransition = rememberInfiniteTransition(label = "pulse")
    val scale by infiniteTransition.animateFloat(
        initialValue = 0.8f,
        targetValue = 1.2f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "scale"
    )

    val alpha by infiniteTransition.animateFloat(
        initialValue = 0.6f,
        targetValue = 0.2f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "alpha"
    )

    Canvas(
        modifier = Modifier
            .size(160.dp)
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
                this.alpha = alpha
            }
    ) {
        drawCircle(
            color = Color(0xFF6366F1),
            radius = size.minDimension / 2,
            style = Stroke(
                width = 4.dp.toPx(),
                pathEffect = PathEffect.dashPathEffect(
                    floatArrayOf(20f, 15f),
                    phase = 0f
                )
            )
        )
    }
}


@Composable
fun GobackOrReload(
    modifier: Modifier = Modifier,
    colors: List<Color>,
    bgColors: List<Color>,
    reloadVisible: Boolean,
    backVisible: Boolean,
    reload: () -> Unit,
    onBack: () -> Unit,
) {
    Row(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(PixelDensity.LARGE),
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (backVisible) {
            HorizontalTextIcon(
                modifier = Modifier
                    .clickable(onClick = onBack)
                    .outline(
                        brush = Brush.linearGradient(
                            colors = colors
                        ),
                        bgBrush = Brush.linearGradient(
                            colors = bgColors
                        ),
                        padding = PixelDensity.MEDIUM
                    ),
                leadingContent = { Icon(TablerIcons.ArrowBack, null) },
                text = "Go Back",
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
            )
        }
        if (reloadVisible) {
            HorizontalTextIcon(
                modifier = Modifier.clickable(onClick = reload).outline(
                    brush = Brush.linearGradient(
                        colors = colors
                    ),
                    bgBrush = Brush.linearGradient(
                        colors = bgColors
                    ),
                    padding = PixelDensity.MEDIUM
                ),
                leadingContent = { Icon(TablerIcons.Refresh, null) },
                text = "Reload",
                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
            )
        }
    }
}

@Composable
fun ShimmeringText(
    modifier: Modifier = Modifier,
    text: String,
    textStyle: TextStyle = MaterialTheme.typography.headlineMedium,
    shimmerColors: List<Color> = listOf(
        Color.White.copy(alpha = 0.6f),
        Color.White,
        Color.White.copy(alpha = 0.6f)
    )
) {
    val infiniteTransition = rememberInfiniteTransition(label = "shimmer")
    val shimmerProgress by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1500, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "shimmer"
    )

    val brush = Brush.linearGradient(
        colors = shimmerColors,
        start = Offset(shimmerProgress * 200f - 100f, 0f),
        end = Offset(shimmerProgress * 200f + 100f, 0f)
    )
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Text(
            text = text,
            style = textStyle,
//            fontSize = 24.sp,
//            fontWeight = FontWeight.Medium,
//            color = Color(0xFF6366F1),
            modifier = Modifier.drawWithContent {
                drawContent()
                drawRect(brush = brush, blendMode = BlendMode.SrcAtop)
            }
        )
    }
}

@Composable
fun GradientCircularProgress() {
    val infiniteTransition = rememberInfiniteTransition(label = "progress")
    val currentProgress by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(2000, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "progress"
    )

    Box(
        modifier = Modifier.size(48.dp),
        contentAlignment = Alignment.Center
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val strokeWidth = 4.dp.toPx()
            val radius = (size.minDimension - strokeWidth) / 2
            val center = Offset(size.width / 2, size.height / 2)
            val angle = currentProgress * 360f

            // Background circle
            drawCircle(
                color = Color(0xFFE2E8F0),
                radius = radius,
                center = center,
                style = Stroke(width = strokeWidth)
            )

            // Gradient arc
            val gradient = Brush.sweepGradient(
                colors = listOf(
                    Color(0xFF6366F1),
                    Color(0xFFEC489A),
                    Color(0xFF06B6D4),
                    Color(0xFF6366F1)
                ),
                center = center
            )

            drawArc(
                brush = gradient,
                startAngle = -90f,
                sweepAngle = angle,
                useCenter = false,
                topLeft = Offset(center.x - radius, center.y - radius),
                size = Size(radius * 2, radius * 2),
                style = Stroke(width = strokeWidth, cap = StrokeCap.Round)
            )
        }

        // Inner pulsing dot
        val pulseScale by infiniteTransition.animateFloat(
            initialValue = 0.8f,
            targetValue = 1.2f,
            animationSpec = infiniteRepeatable(
                animation = tween(800, easing = FastOutSlowInEasing),
                repeatMode = RepeatMode.Reverse
            ),
            label = "pulseScale"
        )

        Canvas(
            modifier = Modifier
                .size(12.dp)
                .scale(pulseScale)
        ) {
            drawCircle(
                color = Color(0xFF6366F1),
                radius = size.minDimension / 2
            )
        }
    }
}
