object OnBoardingScreen : Screen {
    @Composable
    override fun Content() {
        val deviceInfo = rememberDeviceInfo()
        val navigator = LocalNavigator.currentOrThrow
        Scaffold(
            modifier = Modifier.fillMaxSize(),
            floatingActionButton = {
                if (deviceInfo.orientation == Orientation.PORTRAIT) {
                    Column {
                        SmallFloatingActionButton(
                            onClick = { navigator.push(AuthScreen) },
                            content = {
                                Text(
                                    modifier = Modifier.padding(horizontal = PixelDensity.MEDIUM),
                                    text = "Get Started",
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                        )
                        SmallFloatingActionButton(
                            onClick = {
//                                navigator.push(PlaygroundScreen)
                                navigator.push(PlayGSelectVideo)
                                      },
                            content = {
                                Text(
                                    modifier = Modifier.padding(horizontal = PixelDensity.MEDIUM),
                                    text = "Play Ground",
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                        )
                    }
                }
            }
        ) { pv ->
            Column(
                modifier = Modifier
                    .padding(pv)
                    .fillMaxSize()
                    .padding(PixelDensity.MEDIUM)
                    .verticalScrollable(),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
            ) {
                when (deviceInfo.orientation) {
                    Orientation.PORTRAIT -> {
                        WelcomeToKimdeo()
                        DisplayLottie(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(PixelDensity.EXTRA_LARGE),
                            lottiePath = "files/dubbing_lottie.json"
                        )
                        Column(Modifier.padding(PixelDensity.MEDIUM)) {
                            WorldContent(
                                Modifier.padding(bottom = PixelDensity.EXTRA_LARGE)
                            )
                            FeaturesDisplay()
                        }
                    }

                    else -> {
                        Row(
                            Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceAround,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            WelcomeToKimdeo()
                            Spacer(Modifier.width(PixelDensity.MEDIUM))
                            LanguageBarrier()
                        }
                        Row(
                            Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
                        ) {
                            DisplayLottie(
                                modifier = Modifier
                                    .width(PixelDensity.getPixelDensity(deviceInfo.width / 2.1)),
                                lottiePath = "files/dubbing_lottie.json"
                            )
                            Column(Modifier.padding(PixelDensity.MEDIUM)) {
                                WorldContent(
                                    Modifier.padding(bottom = PixelDensity.EXTRA_LARGE)
                                )
                                FeaturesDisplay()

                            }
                        }
                        Row(
                            Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Button(
                                modifier = Modifier.padding(PixelDensity.MEDIUM),
                                onClick = { navigator.push(AuthScreen) }) {
                                Text(
                                    "Get Started",
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                            Spacer(Modifier.width(PixelDensity.EXTRA_LARGE))
                            Button(
                                modifier = Modifier.padding(PixelDensity.MEDIUM),
                                onClick = {
//                                    navigator.push(PlaygroundScreen)
                                    navigator.push(PlayGSelectVideo)
                                }) {
                                Text(
                                    "Play Ground",
                                    style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold)
                                )
                            }
                        }

                    }

                }
            }
        }
    }


    @Composable
    private fun WorldContent(modifier: Modifier = Modifier) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            Text(
                text = "Video player for everyone ",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            Text(
                text = "Leverage AI-powered video analysis to instantly understand what any video is about. Extract valuable information and transform your videos through powerful customization tools.",
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.tertiary
                )
            )
        }
    }

    @Composable
    private fun FeatureDisplayItem(
        modifier: Modifier,
        featureDisplayData: FeatureDisplayData
    ) {

        // High contrast card utilizing a sharp border instead of smooth shadows
        Card(
            colors = CardDefaults.cardColors(
                containerColor = MaterialTheme.colorScheme.surface
            ),
            border = BorderStroke(PixelDensity.VERY_SMALL, MaterialTheme.colorScheme.primary)
        ) {
            Row(
                modifier = modifier,
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
            ) {
                Icon(
                    imageVector = featureDisplayData.imageVector,
                    contentDescription = featureDisplayData.detail,
                    tint = featureDisplayData.iconColor
                )
                VerticalTextIcon(
                    text = featureDisplayData.title,
                    style = MaterialTheme.typography.bodyMedium.copy(
                        fontWeight = FontWeight.Bold,
                        color = featureDisplayData.iconColor
                    ),
                    trailingContent = {
                        Text(
                            text = featureDisplayData.detail,
                            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Bold),
                        )
                    }
                )
            }
        }
    }

    @Composable
    private fun FeaturesDisplay(modifier: Modifier = Modifier) {
        FlowRow(
            modifier,
            horizontalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
        ) {
            for (features in featureDisplayDataList) {
                FeatureDisplayItem(
                    modifier = Modifier.padding(PixelDensity.MEDIUM),
                    featureDisplayData = features
                )
            }
        }
    }

    @Composable
    private fun LanguageBarrier(modifier: Modifier = Modifier) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text(
                text = "Break language barrier ",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            Text(
                text = "Experience the power of AI dubbing, transcribing and translating that works seamlessly",
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center
                )
            )
        }
    }

    @Composable
    private fun WelcomeToKimdeo(
        modifier: Modifier = Modifier
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            StyledText(
                contents = listOf(
                    ComTextModel(
                        text = "Welcome To ",
                        style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                            .toSpanStyle()
                    ),
                    ComTextModel(
                        text = "KimDeo Ai",
                        style = MaterialTheme.typography.headlineMedium.copy(
                            color = MaterialTheme.colorScheme.primary,
                            fontWeight = FontWeight.Bold
                        ).toSpanStyle()
                    )
                )
            )
            Text(
                text = "AI Dubbing, Transcription, Translation & Editing. All in One",
                style = MaterialTheme.typography.bodyMedium.copy(
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center
                )
            )
        }
    }

    @Composable
    private fun DisplayLottie(
        modifier: Modifier,
        lottiePath: String
    ) {
        val composition by rememberLottieComposition {
            LottieCompositionSpec.JsonString(
                Res.readBytes(lottiePath).decodeToString()
            )
        }
        val progress by animateLottieCompositionAsState(
            composition,
            iterations = Compottie.IterateForever
        )
        if (composition != null) {
            Image(
                modifier = modifier,
                painter = rememberLottiePainter(
                    composition = composition,
                    progress = { progress },
                ),
                contentDescription = "Lottie animation"
            )
        } else {
            Box(modifier, contentAlignment = Alignment.Center) {
                PulsingRing()
            }
        }
    }
}


private data class FeatureDisplayData(
    val title: String,
    val detail: String,
    val iconColor: Color,
    val imageVector: ImageVector
)

private val featureDisplayDataList = listOf<FeatureDisplayData>(
    FeatureDisplayData(
        title = "Fast & Accurate",
        detail = "An AI that works with high accuracy",
        iconColor = Color.Blue,
        imageVector = TablerIcons.Strikethrough
    ),
    FeatureDisplayData(
        title = "AI Transcription",
        detail = "Experience fast and high media transcription design to save you valuable time",
        iconColor = Color.Magenta,
        imageVector = TablerIcons.DeviceTv
    ),
    FeatureDisplayData(
        title = "AI Translation",
        detail = "Deliver highly accurate and natural sounding translation across multiple languages",
        iconColor = Color.Cyan,
        imageVector = TablerIcons.Language
    ),
    FeatureDisplayData(
        title = "AI Dubbing",
        detail = "Dub you media with AI voices that sound natively",
        iconColor = Color.Yellow,
        imageVector = TablerIcons.Speakerphone
    )
)