package api.auth.kimdeo.screens.base

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableLongStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import api.auth.kimdeo.core.PreferenceManager
import api.auth.kimdeo.core.api.ApiActions
import api.auth.kimdeo.core.api.ApiActionsFile
import api.auth.kimdeo.model.m_utils.InvokeLogIn
import api.auth.kimdeo.model.user.UserModel
import api.auth.kimdeo.screens.ScreenType
import cafe.adriel.voyager.core.model.ScreenModel
import cafe.adriel.voyager.core.model.screenModelScope
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class BaseScreenModel : ScreenModel {
    var userModel by mutableStateOf<UserModel?>(null)
    var profileImage by mutableStateOf<ByteArray?>(null)
        private set
    val userToken = PreferenceManager.getUserToken()
    val screenName = PreferenceManager.getScreenFlow()
        .stateIn(
            scope = screenModelScope,
            started = SharingStarted.WhileSubscribed(5000),
            initialValue = ScreenType.TRANSCRIBING
        )

    val invokeLogin = PreferenceManager.getInvokeLoginFlow()
        .stateIn(
            scope = screenModelScope,
            started = SharingStarted.WhileSubscribed(5000),
            initialValue = InvokeLogIn.empty()
        )

    var invokeLoginCountDown by mutableLongStateOf(5)

    init {
        screenModelScope.launch {
            if (userToken != null) {
                val u = ApiActions.getUserModelByEmail(userToken.email)
                if (u.data == null) {
                    return@launch
                }
                userModel = u.data
                profileImage = ApiActionsFile.loadFile(userModel?.imagePath, userModel?.userId)
            }
        }
    }

}